Post Record.code:
// POST a record. The path is relative to the credential's baseUrl;
// the bearer token and APIM subscription key are added for you.
http.post(
  // 1) Path.
  '/records',
  // 2) JSON body.
  {
    externalId: $.data.caseId,
    registrationDate: $.data.registrationDate,
    location: $.data.locationCode,
  }
);

List Records.code:
// GET a list of records.
http.request(
  // 1) HTTP method.
  'GET',
  // 2) Path, relative to baseUrl.
  '/records',
  // 3) Body (none for a GET).
  null,
  // 4) Options: query string, extra headers, etc.
  { query: { query: $.data.searchTerm } }
);
